def countPairsWithSum(a, b, target):
    i, j = 0, len(b) - 1
    total = 0
    while i < len(a) and j >= 0:
        s = a[i] + b[j]
        if s < target:
            i += 1
        elif s > target:
            j -= 1
        else:
            x, y = a[i], b[j]
            ca = cb = 0
            while i < len(a) and a[i] == x:
                ca += 1
                i += 1
            while j >= 0 and b[j] == y:
                cb += 1
                j -= 1
            total += ca * cb
    return total
